import React, { Component, Fragment } from "react";
import { Container } from "reactstrap";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import AppNavbar from "./AppNavbar";
import ShoppingList from "./ShoppingList";
import ItemModal from "./ItemModal";
import Clients from "./pages/Clients";
import Items from "./pages/Items";
//import ConfigurationHistory from "./pages/ConfigurationHistory";
import ProcessGroups from "./pages/ProcessGroups";

class Pages extends Component {
  render() {
    const processGroups = (
      <div>
        <ItemModal />
        <ShoppingList />
        <ProcessGroups />
      </div>
    );
    const mainNav = page => {
      switch (page) {
        case "ProcessGroups":
          return processGroups;
        case "Items":
          return <Items />;
        case "Clients":
          return <Clients />;
        default:
          return processGroups;
      }
    };
    const clientsNav = page => {
      switch (page) {
        default:
          return "Client Config";
      }
    };
    const opsNav = page => {
      switch (page) {
        case "ConfigurationHistory":
          //return <ConfigurationHistory />;
          return "config hx";
        case "AccessSetup":
          return "AccessSetup";
        case "ViewAccess":
          return "ViewAccess";
        default:
          return client;
      }
    };

    function renderPageSwitch(page) {
      switch (page.navType) {
        case "MainNav":
          return mainNav(page.page);
        case "OpsNav":
          return opsNav(page.page);
        case "ClientsNav":
          return clientsNav(page.page);
        default:
          return mainNav(page.page);
      }
    }
    return (
      <div>
        <AppNavbar />
        <Container>{renderPageSwitch(this.props.page.page)}</Container>
      </div>
    );
  }
}

Pages.propTypes = {
  page: PropTypes.object.isRequired
};

const mapStateToProps = state => ({
  page: state.page //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
});

export default connect(mapStateToProps, null)(Pages);
